def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    points=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
    # Extend red markers along rows/columns to opposite border markers.
    lines=set()
    for i,(r,c) in enumerate(points):
        for rr,cc in points[i+1:]:
            if r==rr and {c,cc}=={0,w-1}:
                lines.update((r,x) for x in range(w))
            if c==cc and {r,rr}=={0,h-1}:
                lines.update((x,c) for x in range(h))
    # A ray recolors only the 2-object it actually crosses (4-connected objects).
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); component=[]; hit=False
            while stack:
                y,x=stack.pop(); component.append((y,x)); hit |= (y,x) in lines
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==2 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if hit:
                for y,x in component: out[y][x]=1
    for r,c in lines: out[r][c]=1
    return out
